code:
( CIF 2.0 DRC-Clean Polysilicon-to-Metal-1 Contact Cut, 1 lambda = 100 CIF units );
DS 1 100/1;
  9 POLY_M1_CONTACT;
  L CPG;
  B 6 6 3 3;
  L CCP;
  B 3 3 3 3;
  L CMF;
  B 6 6 3 3;
  94 VIA_PIN 3 3 CMF;
DF;
C 1;
E

( Mead-Conway NMOS Inverter Layout in MOSIS SCMOS CIF 2.0 );
DS 10 100/1;
  9 NMOS_INVERTER;
  ( Active diffusion channel for pull-up and pull-down );
  L CAA;
  B 6 24 8 14;
  ( Polysilicon input gate crossing active region );
  L CPG;
  B 16 3 8 8;
  ( Depletion load gate strap );
  L CPG;
  B 8 6 8 19;
  ( Source, drain, and output contacts );
  L CCA;
  B 3 3 8 4;
  B 3 3 8 14;
  B 3 3 8 24;
  ( Metal-1 VDD, GND rails and output wire );
  L CMF;
  B 20 4 10 26;
  B 20 4 10 2;
  W 4 8 14 18 14;
  94 VDD 10 26 CMF;
  94 GND 10 2 CMF;
  94 IN 2 8 CPG;
  94 OUT 18 14 CMF;
DF;
C 10;
E

( MOSIS SCMOS 2-Input Static CMOS NOR Standard Cell );
DS 20 100/1;
  9 CMOS_NOR2;
  ( N-Well >= 10 lambda width );
  L CWN;
  B 30 16 15 26;
  ( PMOS Active inside N-Well );
  L CAA;
  B 24 6 15 24;
  ( NMOS Active below N-Well );
  L CAA;
  B 24 6 15 9;
  ( Dual Polysilicon Gates A and B );
  L CPG;
  B 3 24 10 17;
  B 3 24 20 17;
  ( Active Contacts );
  L CCA;
  B 3 3 5 24;
  B 3 3 25 24;
  B 3 3 5 9;
  B 3 3 15 9;
  B 3 3 25 9;
  ( Metal-1 Power Rails and Output Drain Strap );
  L CMF;
  B 30 4 15 32;
  B 30 4 15 2;
  W 4 5 24 5 32;
  W 4 5 9 5 2;
  W 4 25 9 25 24;
  W 4 15 9 15 2;
  94 VDD 15 32 CMF;
  94 GND 15 2 CMF;
  94 A 10 17 CPG;
  94 B 20 17 CPG;
  94 ZN 25 17 CMF;
DF;
C 20;
E

( Hierarchical 2-Phase Dynamic Shift Register Stage in CIF 2.0 );
DS 1 100/1;
  9 PASS_GATE;
  L CAA;
  B 12 4 6 6;
  L CPG;
  B 3 12 6 6;
  L CCA;
  B 3 3 2 6;
  B 3 3 10 6;
DF;

DS 2 100/1;
  9 INV_STAGE;
  L CWN;
  B 16 14 8 22;
  L CAA;
  B 12 5 8 21;
  B 12 5 8 8;
  L CPG;
  B 3 20 8 15;
  L CMF;
  B 16 4 8 28;
  B 16 4 8 2;
  W 4 12 8 12 21;
DF;

DS 3 100/1;
  9 SHIFT_STAGE_2PH;
  C 1 T 0 6;
  C 2 T 14 0;
  C 1 T 32 6;
  C 2 T 46 0;
  ( Metal-2 Two-Phase Clock Buses PHI1 and PHI2 );
  L CMS;
  W 4 0 34 62 34;
  W 4 0 40 62 40;
  94 PHI1 6 34 CMS;
  94 PHI2 38 40 CMS;
  94 DIN 0 12 CAA;
  94 DOUT 60 15 CMF;
DF;

C 3;
E

( Hierarchical 4-Bit Carry-Lookahead Macrocell with I/O Bonding Pad Ring );
DS 10 100/1;
  9 IO_BOND_PAD;
  L CMF;
  B 16 16 8 8;
  L CMS;
  B 16 16 8 8;
  L CVA;
  B 4 4 8 8;
DF;

DS 20 100/1;
  9 CLA_BIT_SLICE;
  L CWN;
  B 20 16 10 24;
  L CAA;
  B 16 5 10 23;
  B 16 5 10 9;
  L CPG;
  B 3 22 6 16;
  B 3 22 14 16;
  L CCA;
  B 3 3 3 23;
  B 3 3 17 23;
  B 3 3 3 9;
  B 3 3 17 9;
  L CMF;
  B 20 4 10 31;
  B 20 4 10 2;
  W 4 17 9 17 23;
DF;

DS 30 100/1;
  9 CLA_4BIT_MACRO;
  ( Instantiate 4 CLA bit slices horizontally );
  C 20 T 24 24;
  C 20 MX T 66 24;
  C 20 T 68 24;
  C 20 MX T 110 24;
  ( Carry-Propagate and Generate Metal-2 Buses );
  L CMS;
  W 4 24 62 110 62;
  W 4 24 68 110 68;
  ( Perimeter I/O Bonding Pads );
  C 10 T 0 24;
  C 10 T 0 52;
  C 10 T 118 24;
  C 10 T 118 52;
  C 10 T 36 0;
  C 10 T 76 0;
  C 10 T 36 76;
  C 10 T 76 76;
  94 CIN 8 32 CMS;
  94 COUT 126 32 CMS;
  94 VDD_RING 44 84 CMS;
  94 GND_RING 84 8 CMS;
DF;

C 30;
E
